"use strict";

class Wizard {
    constructor(selector, options = {}) {
        this.wizard =
            selector instanceof HTMLElement
                ? selector
                : document.querySelector(selector);

        this.validate = options.validate ?? false;
        this.progress = options.progress ?? false;

        this.selectedIndex = 0;
        this.progressBar = this.progress
            ? this.wizard.querySelector(".tab-content .progress .progress-bar")
            : null;
        this.navItems = this.wizard.querySelectorAll("ul li.nav-item a");
        this.tabPans = this.wizard.querySelectorAll(".tab-content .tab-pane");

        this.prevBtn = this.wizard.querySelector(".tab-content .previous a");
        this.nextBtn = this.wizard.querySelector(".tab-content .next a");
        this.firstBtn = this.wizard.querySelector(".tab-content .first a");
        this.lastBtn = this.wizard.querySelector(
            ".tab-content .last button, .tab-content .last a",
        );

        this.initEventListener();
        this.showTabSelectedTab();
    }

    initEventListener() {
        this.prevBtn?.addEventListener("click", (e) => {
            e.preventDefault();
            if (this.selectedIndex > 0) {
                this.selectedIndex--;
                this.showTabSelectedTab();
            }
        });

        this.nextBtn?.addEventListener("click", (e) => {
            e.preventDefault();

            if (!this.validateCurrentTab()) {
                return;
            }

            if (this.selectedIndex < this.navItems.length - 1) {
                this.selectedIndex++;
                this.showTabSelectedTab();
            }
        });

        this.firstBtn?.addEventListener("click", (e) => {
            e.preventDefault();
            this.selectedIndex = 0;
            this.showTabSelectedTab();
        });

        this.navItems.forEach((item, index) => {
            item.addEventListener("click", (e) => {
                e.preventDefault();

                if (index > this.selectedIndex && !this.validateCurrentTab()) {
                    return;
                }

                this.selectedIndex = index;
                this.showTabSelectedTab();
            });
        });
    }

    showTabSelectedTab() {
        new bootstrap.Tab(this.navItems[this.selectedIndex]).show();

        if (this.progressBar) {
            this.progressBar.style.width =
                ((this.selectedIndex + 1) / this.navItems.length) * 100 + "%";
        }

        this.changeBtnStyle();

        setTimeout(() => {
            if (typeof CKEDITOR !== "undefined") {
                for (let instance in CKEDITOR.instances) {
                    CKEDITOR.instances[instance].resize("100%", 250);
                }
            }
        }, 200);
    }

    changeBtnStyle() {
        this.prevBtn?.classList.toggle("disabled", this.selectedIndex === 0);
        this.firstBtn?.classList.toggle("disabled", this.selectedIndex === 0);

        if (this.selectedIndex === this.navItems.length - 1) {
            this.nextBtn?.classList.add("d-none");
            this.lastBtn?.classList.remove("d-none");
        } else {
            this.nextBtn?.classList.remove("d-none");
            this.lastBtn?.classList.add("d-none");
        }
    }

    validateCurrentTab() {
        if (!this.validate) {
            return true;
        }

        if (typeof CKEDITOR !== "undefined") {
            for (let instance in CKEDITOR.instances) {
                CKEDITOR.instances[instance].updateElement();
            }
        }

        let currentTab = this.tabPans[this.selectedIndex];
        let fields = currentTab.querySelectorAll("input, select, textarea");

        for (let field of fields) {
            if (!field.checkValidity()) {
                field.reportValidity();
                return false;
            }
        }

        return true;
    }
}
